const visual = {
  prepare: function (input) {
    var texts = ['比例尺 1:10000'];
    for (var i = 0; i <= 7; i++) { texts.push(String(i)); }
    texts.push('图上距离 7 厘米');
    texts.push('实际距离 70000 厘米');
    texts.push('单位：厘米');
    var out = [];
    for (var j = 0; j < texts.length; j++) { out.push({ kind: 'text', payload: texts[j] }); }
    return out;
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var x0 = W * 0.12;
    var x1 = W * 0.88;
    var y = H * 0.52;
    var span = x1 - x0;
    var step = span / 7;
    var majorH = H * 0.075;
    var minorH = H * 0.038;
    var endH = H * 0.115;
    var lineColor = '#1F3A5F';
    var accent = '#B03A2E';

    var tickCmds = [];
    var i;
    for (i = 0; i <= 7; i++) {
      var tx = x0 + step * i;
      var th = (i === 0 || i === 7) ? endH : majorH;
      tickCmds.push(['M', tx, y]);
      tickCmds.push(['L', tx, y - th]);
    }
    for (i = 1; i <= 13; i += 2) {
      var mx = x0 + step * (i / 2);
      tickCmds.push(['M', mx, y]);
      tickCmds.push(['L', mx, y - minorH]);
    }

    var arrowY = y + H * 0.10;
    var head = Math.min(span * 0.035, H * 0.028);
    var arrowCmds = [
      ['M', x0, arrowY], ['L', x1, arrowY],
      ['M', x0, arrowY], ['L', x0 + head, arrowY - head * 0.55],
      ['M', x0, arrowY], ['L', x0 + head, arrowY + head * 0.55],
      ['M', x1, arrowY], ['L', x1 - head, arrowY - head * 0.55],
      ['M', x1, arrowY], ['L', x1 - head, arrowY + head * 0.55]
    ];

    var paths = [
      { id: 'baseline', commands: [['M', x0, y], ['L', x1, y]] },
      { id: 'ticks', commands: tickCmds },
      { id: 'spanArrow', commands: arrowCmds }
    ];

    var children = [
      { type: 'path', pathId: 'baseline', fill: lineColor, stroke: { width: 2, cap: 'round' } },
      { type: 'path', pathId: 'ticks', fill: lineColor, stroke: { width: 2, cap: 'round' } },
      { type: 'path', pathId: 'spanArrow', fill: accent, stroke: { width: 2, cap: 'round', join: 'round' } }
    ];

    children.push({ type: 'label', contentId: metrics[0].contentId, anchor: { x: W * 0.5, y: H * 0.13 }, hAlign: 'center', vAlign: 'bottom', color: lineColor });
    children.push({ type: 'label', contentId: metrics[11].contentId, anchor: { x: W * 0.5, y: H * 0.24 }, hAlign: 'center', vAlign: 'middle', color: lineColor });

    for (i = 0; i <= 7; i++) {
      children.push({ type: 'label', contentId: metrics[1 + i].contentId, anchor: { x: x0 + step * i, y: y - endH - H * 0.03 }, hAlign: 'center', vAlign: 'bottom', color: lineColor });
    }

    children.push({ type: 'label', contentId: metrics[9].contentId, anchor: { x: W * 0.5, y: arrowY + H * 0.055 }, hAlign: 'center', vAlign: 'top', color: accent });
    children.push({ type: 'label', contentId: metrics[10].contentId, anchor: { x: W * 0.5, y: H * 0.88 }, hAlign: 'center', vAlign: 'middle', color: accent });

    return {
      schemaVersion: 1,
      sceneId: 'scale-segment',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
